521|static cmark_node *finalize_document(cmark_parser *parser) {
522|  while (parser->current != parser->root) {
523|    parser->current = finalize(parser, parser->current);
524|  }
525|
526|  finalize(parser, parser->root);
527|
528|  // Limit total size of extra content created from reference links to
529|  // document size to avoid superlinear growth. Always allow 100KB.
530|  if (parser->total_size > 100000)
531|    parser->refmap->max_ref_size = parser->total_size;
532|  else
533|    parser->refmap->max_ref_size = 100000;
534|
535|  process_inlines(parser->mem, parser->root, parser->refmap, parser->options);
536|
537|  cmark_strbuf_free(&parser->content);
538|
539|  return parser->root;
540|}

1409|void cmark_parse_inlines(cmark_mem *mem, cmark_node *parent,
1410|                         cmark_reference_map *refmap, int options) {
1411|  int internal_offset = parent->type == CMARK_NODE_HEADING ?
1412|    parent->as.heading.internal_offset : 0;
1413|  subject subj;
1414|  cmark_chunk content = {parent->data, parent->len};
1415|  subject_from_buf(mem, parent->start_line, parent->start_column - 1 + internal_offset, &subj, &content, refmap);
1416|  cmark_chunk_rtrim(&subj.input);
1417|
1418|  while (!is_eof(&subj) && parse_inline(&subj, parent, options))
1419|    ;
1420|
1421|  process_emphasis(&subj, 0);
1422|  // free bracket and delim stack
1423|  while (subj.last_delim) {
1424|    remove_delimiter(&subj, subj.last_delim);
1425|  }
1426|  while (subj.last_bracket) {
1427|    pop_bracket(&subj);
1428|  }
1429|}

154|static int S_render_node(cmark_renderer *renderer, cmark_node *node,
155|                         cmark_event_type ev_type, int options) {
156|  cmark_node *tmp;
157|  int list_number;
158|  cmark_delim_type list_delim;
159|  size_t numticks;
160|  bool extra_spaces;
161|  size_t i;
162|  bool entering = (ev_type == CMARK_EVENT_ENTER);
163|  const char *info, *code, *title;
164|  char fencechar[2] = {'\0', '\0'};
165|  size_t code_len;
166|  char listmarker[LISTMARKER_SIZE];
167|  const char *emph_delim;
168|  bool first_in_list_item;
169|  bufsize_t marker_width;
170|  bool has_nonspace;
171|  bool allow_wrap = renderer->width > 0 && !(CMARK_OPT_NOBREAKS & options) &&
172|                    !(CMARK_OPT_HARDBREAKS & options);
173|
174|  // Don't adjust tight list status til we've started the list.
175|  // Otherwise we lose the blank line between a paragraph and
176|  // a following list.
177|  if (entering) {
178|    if (node->parent && node->parent->type == CMARK_NODE_ITEM) {
179|      renderer->in_tight_list_item = node->parent->parent->as.list.tight;
180|    }
181|  } else {
182|    if (node->type == CMARK_NODE_LIST) {
183|      renderer->in_tight_list_item =
184|        node->parent &&
185|        node->parent->type == CMARK_NODE_ITEM &&
186|        node->parent->parent->as.list.tight;
187|    }
188|  }
189|
190|  switch (node->type) {
191|  case CMARK_NODE_DOCUMENT:
192|    break;
193|
194|  case CMARK_NODE_BLOCK_QUOTE:
195|    if (entering) {
196|      LIT("> ");
197|      renderer->begin_content = true;
198|      cmark_strbuf_puts(renderer->prefix, "> ");
199|    } else {
200|      cmark_strbuf_truncate(renderer->prefix, renderer->prefix->size - 2);
201|      BLANKLINE();
202|    }
203|    break;
204|
205|  case CMARK_NODE_LIST:
206|    if (!entering && node->next && (node->next->type == CMARK_NODE_LIST)) {
207|      // this ensures that a following indented code block or list will be
208|      // inteprereted correctly.
209|      CR();
210|      LIT("<!-- end list -->");
211|      BLANKLINE();
212|    }
213|    break;
214|
215|  case CMARK_NODE_ITEM:
216|    if (cmark_node_get_list_type(node->parent) == CMARK_BULLET_LIST) {
217|      marker_width = 4;
218|    } else {
219|      list_number = cmark_node_get_list_start(node->parent);
220|      list_delim = cmark_node_get_list_delim(node->parent);
221|      tmp = node;
222|      while (tmp->prev) {
223|        tmp = tmp->prev;
224|        list_number += 1;
225|      }
226|      // we ensure a width of at least 4 so
227|      // we get nice transition from single digits
228|      // to double
229|      snprintf(listmarker, LISTMARKER_SIZE, "%d%s%s", list_number,
230|               list_delim == CMARK_PAREN_DELIM ? ")" : ".",
231|               list_number < 10 ? "  " : " ");
232|      marker_width = (bufsize_t)strlen(listmarker);
233|    }
234|    if (entering) {
235|      if (cmark_node_get_list_type(node->parent) == CMARK_BULLET_LIST) {
236|        LIT("  - ");
237|        renderer->begin_content = true;
238|      } else {
239|        LIT(listmarker);
240|        renderer->begin_content = true;
241|      }
242|      for (i = marker_width; i--;) {
243|        cmark_strbuf_putc(renderer->prefix, ' ');
244|      }
245|    } else {
246|      cmark_strbuf_truncate(renderer->prefix,
247|                            renderer->prefix->size - marker_width);
248|      CR();
249|    }
250|    break;
251|
252|  case CMARK_NODE_HEADING:
253|    if (entering) {
254|      for (i = cmark_node_get_heading_level(node); i > 0; i--) {
255|        LIT("#");
256|      }
257|      LIT(" ");
258|      renderer->begin_content = true;
259|      renderer->no_linebreaks = true;
260|    } else {
261|      renderer->no_linebreaks = false;
262|      BLANKLINE();
263|    }
264|    break;
265|
266|  case CMARK_NODE_CODE_BLOCK:
267|
268|    first_in_list_item = node->prev == NULL && node->parent &&
269|                         node->parent->type == CMARK_NODE_ITEM;
270|
271|    if (!first_in_list_item) {
272|      BLANKLINE();
273|    }
274|    info = cmark_node_get_fence_info(node);
275|    fencechar[0] = strchr(info, '`') == NULL ? '`' : '~';
276|    code = cmark_node_get_literal(node);
277|
278|    numticks = longest_backtick_sequence(code) + 1;
279|    if (numticks < 3) {
280|      numticks = 3;
281|    }
282|    for (i = 0; i < numticks; i++) {
283|      LIT(fencechar);
284|    }
285|    LIT(" ");
286|    OUT(info, false, LITERAL);
287|    CR();
288|    OUT(cmark_node_get_literal(node), false, LITERAL);
289|    CR();
290|    for (i = 0; i < numticks; i++) {
291|      LIT(fencechar);
292|    }
293|
294|    BLANKLINE();
295|    break;
296|
297|  case CMARK_NODE_HTML_BLOCK:
298|    BLANKLINE();
299|    OUT(cmark_node_get_literal(node), false, LITERAL);
300|    BLANKLINE();
301|    break;
302|
303|  case CMARK_NODE_CUSTOM_BLOCK:
304|    BLANKLINE();
305|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
306|        false, LITERAL);
307|    BLANKLINE();
308|    break;
309|
310|  case CMARK_NODE_THEMATIC_BREAK:
311|    BLANKLINE();
312|    LIT("-----");
313|    BLANKLINE();
314|    break;
315|
316|  case CMARK_NODE_PARAGRAPH:
317|    if (!entering) {
318|      BLANKLINE();
319|    }
320|    break;
321|
322|  case CMARK_NODE_TEXT:
323|    OUT(cmark_node_get_literal(node), allow_wrap, NORMAL);
324|    break;
325|
326|  case CMARK_NODE_LINEBREAK:
327|    if (!(CMARK_OPT_HARDBREAKS & options)) {
328|      LIT("  ");
329|    }
330|    CR();
331|    break;
332|
333|  case CMARK_NODE_SOFTBREAK:
334|    if (CMARK_OPT_HARDBREAKS & options) {
335|      LIT("  ");
336|      CR();
337|    } else if (!renderer->no_linebreaks && renderer->width == 0 &&
338|               !(CMARK_OPT_HARDBREAKS & options) &&
339|               !(CMARK_OPT_NOBREAKS & options)) {
340|      CR();
341|    } else {
342|      OUT(" ", allow_wrap, LITERAL);
343|    }
344|    break;
345|
346|  case CMARK_NODE_CODE:
347|    code = cmark_node_get_literal(node);
348|    code_len = strlen(code);
349|    numticks = shortest_unused_backtick_sequence(code);
350|    has_nonspace = false;
351|    for (i=0; i < code_len; i++) {
352|      if (code[i] != ' ') {
353|        has_nonspace = true;
354|        break;
355|      }
356|    }
357|    extra_spaces = code_len == 0 ||
358|            code[0] == '`' || code[code_len - 1] == '`' ||
359|            (has_nonspace && code[0] == ' ' && code[code_len - 1] == ' ');
360|    for (i = 0; i < numticks; i++) {
361|      LIT("`");
362|    }
363|    if (extra_spaces) {
364|      LIT(" ");
365|    }
366|    OUT(cmark_node_get_literal(node), allow_wrap, LITERAL);
367|    if (extra_spaces) {
368|      LIT(" ");
369|    }
370|    for (i = 0; i < numticks; i++) {
371|      LIT("`");
372|    }
373|    break;
374|
375|  case CMARK_NODE_HTML_INLINE:
376|    OUT(cmark_node_get_literal(node), false, LITERAL);
377|    break;
378|
379|  case CMARK_NODE_CUSTOM_INLINE:
380|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
381|        false, LITERAL);
382|    break;
383|
384|  case CMARK_NODE_STRONG:
385|    if (entering) {
386|      LIT("**");
387|    } else {
388|      LIT("**");
389|    }
390|    break;
391|
392|  case CMARK_NODE_EMPH:
393|    // If we have EMPH(EMPH(x)), we need to use *_x_*
394|    // because **x** is STRONG(x):
395|    if (node->parent && node->parent->type == CMARK_NODE_EMPH &&
396|        node->next == NULL && node->prev == NULL) {
397|      emph_delim = "_";
398|    } else {
399|      emph_delim = "*";
400|    }
401|    if (entering) {
402|      LIT(emph_delim);
403|    } else {
404|      LIT(emph_delim);
405|    }
406|    break;
407|
408|  case CMARK_NODE_LINK:
409|    if (is_autolink(node)) {
410|      if (entering) {
411|        LIT("<");
412|        if (strncmp(cmark_node_get_url(node), "mailto:", 7) == 0) {
413|          LIT((const char *)cmark_node_get_url(node) + 7);
414|        } else {
415|          LIT((const char *)cmark_node_get_url(node));
416|        }
417|        LIT(">");
418|        // return signal to skip contents of node...
419|        return 0;
420|      }
421|    } else {
422|      if (entering) {
423|        LIT("[");
424|      } else {
425|        LIT("](");
426|        OUT(cmark_node_get_url(node), false, URL);
427|        title = cmark_node_get_title(node);
428|        if (strlen(title) > 0) {
429|          LIT(" \"");
430|          OUT(title, false, TITLE);
431|          LIT("\"");
432|        }
433|        LIT(")");
434|      }
435|    }
436|    break;
437|
438|  case CMARK_NODE_IMAGE:
439|    if (entering) {
440|      LIT("![");
441|    } else {
442|      LIT("](");
443|      OUT(cmark_node_get_url(node), false, URL);
444|      title = cmark_node_get_title(node);
445|      if (strlen(title) > 0) {
446|        OUT(" \"", allow_wrap, LITERAL);
447|        OUT(title, false, TITLE);
448|        LIT("\"");
449|      }
450|      LIT(")");
451|    }
452|    break;
453|
454|  default:
455|    assert(false);
456|    break;
457|  }
458|
459|  return 1;
460|}

44|static int S_render_node(cmark_node *node, cmark_event_type ev_type,
45|                         struct render_state *state, int options) {
46|  cmark_node *parent;
47|  cmark_node *grandparent;
48|  cmark_strbuf *html = state->html;
49|  char start_heading[] = "<h0";
50|  char end_heading[] = "</h0";
51|  bool tight;
52|  char buffer[BUFFER_SIZE];
53|
54|  bool entering = (ev_type == CMARK_EVENT_ENTER);
55|
56|  if (state->plain == node) { // back at original node
57|    state->plain = NULL;
58|  }
59|
60|  if (state->plain != NULL) {
61|    switch (node->type) {
62|    case CMARK_NODE_TEXT:
63|    case CMARK_NODE_CODE:
64|    case CMARK_NODE_HTML_INLINE:
65|      escape_html(html, node->data, node->len);
66|      break;
67|
68|    case CMARK_NODE_LINEBREAK:
69|    case CMARK_NODE_SOFTBREAK:
70|      cmark_strbuf_putc(html, ' ');
71|      break;
72|
73|    default:
74|      break;
75|    }
76|    return 1;
77|  }
78|
79|  switch (node->type) {
80|  case CMARK_NODE_DOCUMENT:
81|    break;
82|
83|  case CMARK_NODE_BLOCK_QUOTE:
84|    if (entering) {
85|      cr(html);
86|      cmark_strbuf_puts(html, "<blockquote");
87|      S_render_sourcepos(node, html, options);
88|      cmark_strbuf_puts(html, ">\n");
89|    } else {
90|      cr(html);
91|      cmark_strbuf_puts(html, "</blockquote>\n");
92|    }
93|    break;
94|
95|  case CMARK_NODE_LIST: {
96|    cmark_list_type list_type = (cmark_list_type)node->as.list.list_type;
97|    int start = node->as.list.start;
98|
99|    if (entering) {
100|      cr(html);
101|      if (list_type == CMARK_BULLET_LIST) {
102|        cmark_strbuf_puts(html, "<ul");
103|        S_render_sourcepos(node, html, options);
104|        cmark_strbuf_puts(html, ">\n");
105|      } else if (start == 1) {
106|        cmark_strbuf_puts(html, "<ol");
107|        S_render_sourcepos(node, html, options);
108|        cmark_strbuf_puts(html, ">\n");
109|      } else {
110|        snprintf(buffer, BUFFER_SIZE, "<ol start=\"%d\"", start);
111|        cmark_strbuf_puts(html, buffer);
112|        S_render_sourcepos(node, html, options);
113|        cmark_strbuf_puts(html, ">\n");
114|      }
115|    } else {
116|      cmark_strbuf_puts(html,
117|                        list_type == CMARK_BULLET_LIST ? "</ul>\n" : "</ol>\n");
118|    }
119|    break;
120|  }
121|
122|  case CMARK_NODE_ITEM:
123|    if (entering) {
124|      cr(html);
125|      cmark_strbuf_puts(html, "<li");
126|      S_render_sourcepos(node, html, options);
127|      cmark_strbuf_putc(html, '>');
128|    } else {
129|      cmark_strbuf_puts(html, "</li>\n");
130|    }
131|    break;
132|
133|  case CMARK_NODE_HEADING:
134|    if (entering) {
135|      cr(html);
136|      start_heading[2] = (char)('0' + node->as.heading.level);
137|      cmark_strbuf_puts(html, start_heading);
138|      S_render_sourcepos(node, html, options);
139|      cmark_strbuf_putc(html, '>');
140|    } else {
141|      end_heading[3] = (char)('0' + node->as.heading.level);
142|      cmark_strbuf_puts(html, end_heading);
143|      cmark_strbuf_puts(html, ">\n");
144|    }
145|    break;
146|
147|  case CMARK_NODE_CODE_BLOCK:
148|    cr(html);
149|
150|    if (node->as.code.info == NULL || node->as.code.info[0] == 0) {
151|      cmark_strbuf_puts(html, "<pre");
152|      S_render_sourcepos(node, html, options);
153|      cmark_strbuf_puts(html, "><code>");
154|    } else {
155|      bufsize_t first_tag = 0;
156|      while (node->as.code.info[first_tag] &&
157|             !cmark_isspace(node->as.code.info[first_tag])) {
158|        first_tag += 1;
159|      }
160|
161|      cmark_strbuf_puts(html, "<pre");
162|      S_render_sourcepos(node, html, options);
163|      cmark_strbuf_puts(html, "><code class=\"");
164|      if (strncmp((char *)node->as.code.info, "language-", 9) != 0) {
165|        cmark_strbuf_puts(html, "language-");
166|      }
167|      escape_html(html, node->as.code.info, first_tag);
168|      cmark_strbuf_puts(html, "\">");
169|    }
170|
171|    escape_html(html, node->data, node->len);
172|    cmark_strbuf_puts(html, "</code></pre>\n");
173|    break;
174|
175|  case CMARK_NODE_HTML_BLOCK:
176|    cr(html);
177|    if (!(options & CMARK_OPT_UNSAFE)) {
178|      cmark_strbuf_puts(html, "<!-- raw HTML omitted -->");
179|    } else {
180|      cmark_strbuf_put(html, node->data, node->len);
181|    }
182|    cr(html);
183|    break;
184|
185|  case CMARK_NODE_CUSTOM_BLOCK: {
186|    unsigned char *block = entering ? node->as.custom.on_enter :
187|                                      node->as.custom.on_exit;
188|    cr(html);
189|    if (block) {
190|      cmark_strbuf_puts(html, (char *)block);
191|    }
192|    cr(html);
193|    break;
194|  }
195|
196|  case CMARK_NODE_THEMATIC_BREAK:
197|    cr(html);
198|    cmark_strbuf_puts(html, "<hr");
199|    S_render_sourcepos(node, html, options);
200|    cmark_strbuf_puts(html, " />\n");
201|    break;
202|
203|  case CMARK_NODE_PARAGRAPH:
204|    parent = cmark_node_parent(node);
205|    grandparent = cmark_node_parent(parent);
206|    if (grandparent != NULL && grandparent->type == CMARK_NODE_LIST) {
207|      tight = grandparent->as.list.tight;
208|    } else {
209|      tight = false;
210|    }
211|    if (!tight) {
212|      if (entering) {
213|        cr(html);
214|        cmark_strbuf_puts(html, "<p");
215|        S_render_sourcepos(node, html, options);
216|        cmark_strbuf_putc(html, '>');
217|      } else {
218|        cmark_strbuf_puts(html, "</p>\n");
219|      }
220|    }
221|    break;
222|
223|  case CMARK_NODE_TEXT:
224|    escape_html(html, node->data, node->len);
225|    break;
226|
227|  case CMARK_NODE_LINEBREAK:
228|    cmark_strbuf_puts(html, "<br />\n");
229|    break;
230|
231|  case CMARK_NODE_SOFTBREAK:
232|    if (options & CMARK_OPT_HARDBREAKS) {
233|      cmark_strbuf_puts(html, "<br />\n");
234|    } else if (options & CMARK_OPT_NOBREAKS) {
235|      cmark_strbuf_putc(html, ' ');
236|    } else {
237|      cmark_strbuf_putc(html, '\n');
238|    }
239|    break;
240|
241|  case CMARK_NODE_CODE:
242|    cmark_strbuf_puts(html, "<code>");
243|    escape_html(html, node->data, node->len);
244|    cmark_strbuf_puts(html, "</code>");
245|    break;
246|
247|  case CMARK_NODE_HTML_INLINE:
248|    if (!(options & CMARK_OPT_UNSAFE)) {
249|      cmark_strbuf_puts(html, "<!-- raw HTML omitted -->");
250|    } else {
251|      cmark_strbuf_put(html, node->data, node->len);
252|    }
253|    break;
254|
255|  case CMARK_NODE_CUSTOM_INLINE: {
256|    unsigned char *block = entering ? node->as.custom.on_enter :
257|                                      node->as.custom.on_exit;
258|    if (block) {
259|      cmark_strbuf_puts(html, (char *)block);
260|    }
261|    break;
262|  }
263|
264|  case CMARK_NODE_STRONG:
265|    if (entering) {
266|      cmark_strbuf_puts(html, "<strong>");
267|    } else {
268|      cmark_strbuf_puts(html, "</strong>");
269|    }
270|    break;
271|
272|  case CMARK_NODE_EMPH:
273|    if (entering) {
274|      cmark_strbuf_puts(html, "<em>");
275|    } else {
276|      cmark_strbuf_puts(html, "</em>");
277|    }
278|    break;
279|
280|  case CMARK_NODE_LINK:
281|    if (entering) {
282|      cmark_strbuf_puts(html, "<a href=\"");
283|      if (node->as.link.url && ((options & CMARK_OPT_UNSAFE) ||
284|                                !(_scan_dangerous_url(node->as.link.url)))) {
285|        houdini_escape_href(html, node->as.link.url,
286|                            (bufsize_t)strlen((char *)node->as.link.url));
287|      }
288|      if (node->as.link.title) {
289|        cmark_strbuf_puts(html, "\" title=\"");
290|        escape_html(html, node->as.link.title,
291|                    (bufsize_t)strlen((char *)node->as.link.title));
292|      }
293|      cmark_strbuf_puts(html, "\">");
294|    } else {
295|      cmark_strbuf_puts(html, "</a>");
296|    }
297|    break;
298|
299|  case CMARK_NODE_IMAGE:
300|    if (entering) {
301|      cmark_strbuf_puts(html, "<img src=\"");
302|      if (node->as.link.url && ((options & CMARK_OPT_UNSAFE) ||
303|                                !(_scan_dangerous_url(node->as.link.url)))) {
304|        houdini_escape_href(html, node->as.link.url,
305|                            (bufsize_t)strlen((char *)node->as.link.url));
306|      }
307|      cmark_strbuf_puts(html, "\" alt=\"");
308|      state->plain = node;
309|    } else {
310|      if (node->as.link.title) {
311|        cmark_strbuf_puts(html, "\" title=\"");
312|        escape_html(html, node->as.link.title,
313|                    (bufsize_t)strlen((char *)node->as.link.title));
314|      }
315|
316|      cmark_strbuf_puts(html, "\" />");
317|    }
318|    break;
319|
320|  default:
321|    assert(false);
322|    break;
323|  }
324|
325|  // cmark_strbuf_putc(html, 'x');
326|  return 1;
327|}

220|static int S_render_node(cmark_renderer *renderer, cmark_node *node,
221|                         cmark_event_type ev_type, int options) {
222|  int list_number;
223|  int enumlevel;
224|  char list_number_string[LIST_NUMBER_STRING_SIZE];
225|  bool entering = (ev_type == CMARK_EVENT_ENTER);
226|  cmark_list_type list_type;
227|  bool allow_wrap = renderer->width > 0 && !(CMARK_OPT_NOBREAKS & options);
228|
229|  // avoid warning about unused parameter:
230|  (void)(options);
231|
232|  switch (node->type) {
233|  case CMARK_NODE_DOCUMENT:
234|    break;
235|
236|  case CMARK_NODE_BLOCK_QUOTE:
237|    if (entering) {
238|      LIT("\\begin{quote}");
239|      CR();
240|    } else {
241|      LIT("\\end{quote}");
242|      BLANKLINE();
243|    }
244|    break;
245|
246|  case CMARK_NODE_LIST:
247|    list_type = cmark_node_get_list_type(node);
248|    if (entering) {
249|      LIT("\\begin{");
250|      LIT(list_type == CMARK_ORDERED_LIST ? "enumerate" : "itemize");
251|      LIT("}");
252|      CR();
253|      list_number = cmark_node_get_list_start(node);
254|      if (list_number > 1) {
255|        enumlevel = S_get_enumlevel(node);
256|        // latex normally supports only five levels
257|        if (enumlevel >= 1 && enumlevel <= 5) {
258|          snprintf(list_number_string, LIST_NUMBER_STRING_SIZE, "%d",
259|                   list_number - 1); // the next item will increment this
260|          LIT("\\setcounter{enum");
261|          switch (enumlevel) {
262|          case 1: LIT("i"); break;
263|          case 2: LIT("ii"); break;
264|          case 3: LIT("iii"); break;
265|          case 4: LIT("iv"); break;
266|          case 5: LIT("v"); break;
267|          default: LIT("i"); break;
268|          }
269|          LIT("}{");
270|          OUT(list_number_string, false, NORMAL);
271|          LIT("}");
272|        }
273|        CR();
274|      }
275|    } else {
276|      LIT("\\end{");
277|      LIT(list_type == CMARK_ORDERED_LIST ? "enumerate" : "itemize");
278|      LIT("}");
279|      BLANKLINE();
280|    }
281|    break;
282|
283|  case CMARK_NODE_ITEM:
284|    if (entering) {
285|      LIT("\\item ");
286|    } else {
287|      CR();
288|    }
289|    break;
290|
291|  case CMARK_NODE_HEADING:
292|    if (entering) {
293|      switch (cmark_node_get_heading_level(node)) {
294|      case 1:
295|        LIT("\\section");
296|        break;
297|      case 2:
298|        LIT("\\subsection");
299|        break;
300|      case 3:
301|        LIT("\\subsubsection");
302|        break;
303|      case 4:
304|        LIT("\\paragraph");
305|        break;
306|      case 5:
307|        LIT("\\subparagraph");
308|        break;
309|      }
310|      LIT("{");
311|    } else {
312|      LIT("}");
313|      BLANKLINE();
314|    }
315|    break;
316|
317|  case CMARK_NODE_CODE_BLOCK:
318|    CR();
319|    LIT("\\begin{verbatim}");
320|    CR();
321|    OUT(cmark_node_get_literal(node), false, LITERAL);
322|    CR();
323|    LIT("\\end{verbatim}");
324|    BLANKLINE();
325|    break;
326|
327|  case CMARK_NODE_HTML_BLOCK:
328|    break;
329|
330|  case CMARK_NODE_CUSTOM_BLOCK:
331|    CR();
332|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
333|        false, LITERAL);
334|    CR();
335|    break;
336|
337|  case CMARK_NODE_THEMATIC_BREAK:
338|    BLANKLINE();
339|    LIT("\\begin{center}\\rule{0.5\\linewidth}{\\linethickness}\\end{center}");
340|    BLANKLINE();
341|    break;
342|
343|  case CMARK_NODE_PARAGRAPH:
344|    if (!entering) {
345|      BLANKLINE();
346|    }
347|    break;
348|
349|  case CMARK_NODE_TEXT:
350|    OUT(cmark_node_get_literal(node), allow_wrap, NORMAL);
351|    break;
352|
353|  case CMARK_NODE_LINEBREAK:
354|    LIT("\\\\");
355|    CR();
356|    break;
357|
358|  case CMARK_NODE_SOFTBREAK:
359|    if (options & CMARK_OPT_HARDBREAKS) {
360|      LIT("\\\\");
361|      CR();
362|    } else if (renderer->width == 0 && !(CMARK_OPT_NOBREAKS & options)) {
363|      CR();
364|    } else {
365|      OUT(" ", allow_wrap, NORMAL);
366|    }
367|    break;
368|
369|  case CMARK_NODE_CODE:
370|    LIT("\\texttt{");
371|    OUT(cmark_node_get_literal(node), false, NORMAL);
372|    LIT("}");
373|    break;
374|
375|  case CMARK_NODE_HTML_INLINE:
376|    break;
377|
378|  case CMARK_NODE_CUSTOM_INLINE:
379|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
380|        false, LITERAL);
381|    break;
382|
383|  case CMARK_NODE_STRONG:
384|    if (entering) {
385|      LIT("\\textbf{");
386|    } else {
387|      LIT("}");
388|    }
389|    break;
390|
391|  case CMARK_NODE_EMPH:
392|    if (entering) {
393|      LIT("\\emph{");
394|    } else {
395|      LIT("}");
396|    }
397|    break;
398|
399|  case CMARK_NODE_LINK:
400|    if (entering) {
401|      const char *url = cmark_node_get_url(node);
402|      // requires \usepackage{hyperref}
403|      switch (get_link_type(node)) {
404|      case URL_AUTOLINK:
405|        LIT("\\url{");
406|        OUT(url, false, URL);
407|        LIT("}");
408|        return 0; // Don't process further nodes to avoid double-rendering artefacts
409|      case EMAIL_AUTOLINK:
410|        LIT("\\href{");
411|        OUT(url, false, URL);
412|        LIT("}\\nolinkurl{");
413|        break;
414|      case NORMAL_LINK:
415|        LIT("\\href{");
416|        OUT(url, false, URL);
417|        LIT("}{");
418|        break;
419|      case INTERNAL_LINK:
420|        LIT("\\protect\\hyperlink{");
421|        OUT(url + 1, false, URL);
422|        LIT("}{");
423|        break;
424|      case NO_LINK:
425|        LIT("{"); // error?
426|      }
427|    } else {
428|      LIT("}");
429|    }
430|
431|    break;
432|
433|  case CMARK_NODE_IMAGE:
434|    if (entering) {
435|      LIT("\\protect\\includegraphics{");
436|      // requires \include{graphicx}
437|      OUT(cmark_node_get_url(node), false, URL);
438|      LIT("}");
439|      return 0;
440|    }
441|    break;
442|
443|  default:
444|    assert(false);
445|    break;
446|  }
447|
448|  return 1;
449|}

73|static int S_render_node(cmark_renderer *renderer, cmark_node *node,
74|                         cmark_event_type ev_type, int options) {
75|  cmark_node *tmp;
76|  int list_number;
77|  bool entering = (ev_type == CMARK_EVENT_ENTER);
78|  bool allow_wrap = renderer->width > 0 && !(CMARK_OPT_NOBREAKS & options);
79|  struct block_number *new_block_number;
80|  cmark_mem *allocator = cmark_get_default_mem_allocator();
81|
82|  // avoid unused parameter error:
83|  (void)(options);
84|
85|  // indent inside nested lists
86|  if (renderer->block_number_in_list_item &&
87|      node->type < CMARK_NODE_FIRST_INLINE) {
88|    if (entering) {
89|      renderer->block_number_in_list_item->number += 1;
90|      if (renderer->block_number_in_list_item->number == 2) {
91|        CR();
92|        LIT(".RS"); // indent
93|        CR();
94|      }
95|    }
96|  }
97|
98|  switch (node->type) {
99|  case CMARK_NODE_DOCUMENT:
100|    break;
101|
102|  case CMARK_NODE_BLOCK_QUOTE:
103|    if (entering) {
104|      CR();
105|      LIT(".RS");
106|      CR();
107|    } else {
108|      CR();
109|      LIT(".RE");
110|      CR();
111|    }
112|    break;
113|
114|  case CMARK_NODE_LIST:
115|    break;
116|
117|  case CMARK_NODE_ITEM:
118|    if (entering) {
119|      new_block_number = allocator->calloc(1, sizeof(struct block_number));
120|      new_block_number->number = 0;
121|      new_block_number->parent = renderer->block_number_in_list_item;
122|      renderer->block_number_in_list_item = new_block_number;
123|      CR();
124|      LIT(".IP ");
125|      if (cmark_node_get_list_type(node->parent) == CMARK_BULLET_LIST) {
126|        LIT("\\[bu] 2");
127|      } else {
128|        list_number = cmark_node_get_list_start(node->parent);
129|        tmp = node;
130|        while (tmp->prev) {
131|          tmp = tmp->prev;
132|          list_number += 1;
133|        }
134|        char list_number_s[LIST_NUMBER_SIZE];
135|        snprintf(list_number_s, LIST_NUMBER_SIZE, "\"%d.\" 4", list_number);
136|        LIT(list_number_s);
137|      }
138|      CR();
139|    } else {
140|      if (renderer->block_number_in_list_item) {
141|        if (renderer->block_number_in_list_item->number >= 2) {
142|          CR();
143|          LIT(".RE"); // de-indent
144|        }
145|        new_block_number = renderer->block_number_in_list_item;
146|        renderer->block_number_in_list_item =
147|          renderer->block_number_in_list_item->parent;
148|        allocator->free(new_block_number);
149|      }
150|      CR();
151|    }
152|    break;
153|
154|  case CMARK_NODE_HEADING:
155|    if (entering) {
156|      CR();
157|      LIT(cmark_node_get_heading_level(node) == 1 ? ".SH" : ".SS");
158|      CR();
159|    } else {
160|      CR();
161|    }
162|    break;
163|
164|  case CMARK_NODE_CODE_BLOCK:
165|    CR();
166|    LIT(".IP\n.nf\n\\f[C]\n");
167|    OUT(cmark_node_get_literal(node), false, NORMAL);
168|    CR();
169|    LIT("\\f[]\n.fi");
170|    CR();
171|    break;
172|
173|  case CMARK_NODE_HTML_BLOCK:
174|    break;
175|
176|  case CMARK_NODE_CUSTOM_BLOCK:
177|    CR();
178|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
179|        false, LITERAL);
180|    CR();
181|    break;
182|
183|  case CMARK_NODE_THEMATIC_BREAK:
184|    CR();
185|    LIT(".PP\n  *  *  *  *  *");
186|    CR();
187|    break;
188|
189|  case CMARK_NODE_PARAGRAPH:
190|    if (entering) {
191|      // no blank line if first paragraph in list:
192|      if (node->parent && node->parent->type == CMARK_NODE_ITEM &&
193|          node->prev == NULL) {
194|        // no blank line or .PP
195|      } else {
196|        CR();
197|        LIT(".PP");
198|        CR();
199|      }
200|    } else {
201|      CR();
202|    }
203|    break;
204|
205|  case CMARK_NODE_TEXT:
206|    OUT(cmark_node_get_literal(node), allow_wrap, NORMAL);
207|    break;
208|
209|  case CMARK_NODE_LINEBREAK:
210|    LIT(".PD 0\n.P\n.PD");
211|    CR();
212|    break;
213|
214|  case CMARK_NODE_SOFTBREAK:
215|    if (options & CMARK_OPT_HARDBREAKS) {
216|      LIT(".PD 0\n.P\n.PD");
217|      CR();
218|    } else if (renderer->width == 0 && !(CMARK_OPT_NOBREAKS & options)) {
219|      CR();
220|    } else {
221|      OUT(" ", allow_wrap, LITERAL);
222|    }
223|    break;
224|
225|  case CMARK_NODE_CODE:
226|    LIT("\\f[C]");
227|    OUT(cmark_node_get_literal(node), allow_wrap, NORMAL);
228|    LIT("\\f[]");
229|    break;
230|
231|  case CMARK_NODE_HTML_INLINE:
232|    break;
233|
234|  case CMARK_NODE_CUSTOM_INLINE:
235|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
236|        false, LITERAL);
237|    break;
238|
239|  case CMARK_NODE_STRONG:
240|    if (entering) {
241|      LIT("\\f[B]");
242|    } else {
243|      LIT("\\f[]");
244|    }
245|    break;
246|
247|  case CMARK_NODE_EMPH:
248|    if (entering) {
249|      LIT("\\f[I]");
250|    } else {
251|      LIT("\\f[]");
252|    }
253|    break;
254|
255|  case CMARK_NODE_LINK:
256|    if (!entering) {
257|      LIT(" (");
258|      OUT(cmark_node_get_url(node), allow_wrap, URL);
259|      LIT(")");
260|    }
261|    break;
262|
263|  case CMARK_NODE_IMAGE:
264|    if (entering) {
265|      LIT("[IMAGE: ");
266|    } else {
267|      LIT("]");
268|    }
269|    break;
270|
271|  default:
272|    assert(false);
273|    break;
274|  }
275|
276|  return 1;
277|}

92|static int S_render_node(cmark_node *node, cmark_event_type ev_type,
93|                         struct render_state *state, int options) {
94|  cmark_strbuf *xml = state->xml;
95|  bool literal = false;
96|  cmark_delim_type delim;
97|  bool entering = (ev_type == CMARK_EVENT_ENTER);
98|  char buffer[BUFFER_SIZE];
99|
100|  if (entering) {
101|    indent(state);
102|    cmark_strbuf_putc(xml, '<');
103|    cmark_strbuf_puts(xml, cmark_node_get_type_string(node));
104|
105|    if (options & CMARK_OPT_SOURCEPOS && node->start_line != 0) {
106|      snprintf(buffer, BUFFER_SIZE, " sourcepos=\"%d:%d-%d:%d\"",
107|               node->start_line, node->start_column, node->end_line,
108|               node->end_column);
109|      cmark_strbuf_puts(xml, buffer);
110|    }
111|
112|    literal = false;
113|
114|    switch (node->type) {
115|    case CMARK_NODE_DOCUMENT:
116|      cmark_strbuf_puts(xml, " xmlns=\"http://commonmark.org/xml/1.0\"");
117|      break;
118|    case CMARK_NODE_TEXT:
119|    case CMARK_NODE_CODE:
120|    case CMARK_NODE_HTML_BLOCK:
121|    case CMARK_NODE_HTML_INLINE:
122|      cmark_strbuf_puts(xml, " xml:space=\"preserve\">");
123|      escape_xml(xml, node->data, node->len);
124|      cmark_strbuf_puts(xml, "</");
125|      cmark_strbuf_puts(xml, cmark_node_get_type_string(node));
126|      literal = true;
127|      break;
128|    case CMARK_NODE_LIST:
129|      switch (cmark_node_get_list_type(node)) {
130|      case CMARK_ORDERED_LIST:
131|        cmark_strbuf_puts(xml, " type=\"ordered\"");
132|        snprintf(buffer, BUFFER_SIZE, " start=\"%d\"",
133|                 cmark_node_get_list_start(node));
134|        cmark_strbuf_puts(xml, buffer);
135|        delim = cmark_node_get_list_delim(node);
136|        if (delim == CMARK_PAREN_DELIM) {
137|          cmark_strbuf_puts(xml, " delim=\"paren\"");
138|        } else if (delim == CMARK_PERIOD_DELIM) {
139|          cmark_strbuf_puts(xml, " delim=\"period\"");
140|        }
141|        break;
142|      case CMARK_BULLET_LIST:
143|        cmark_strbuf_puts(xml, " type=\"bullet\"");
144|        break;
145|      default:
146|        break;
147|      }
148|      snprintf(buffer, BUFFER_SIZE, " tight=\"%s\"",
149|               (cmark_node_get_list_tight(node) ? "true" : "false"));
150|      cmark_strbuf_puts(xml, buffer);
151|      break;
152|    case CMARK_NODE_HEADING:
153|      snprintf(buffer, BUFFER_SIZE, " level=\"%d\"", node->as.heading.level);
154|      cmark_strbuf_puts(xml, buffer);
155|      break;
156|    case CMARK_NODE_CODE_BLOCK:
157|      if (node->as.code.info) {
158|        cmark_strbuf_puts(xml, " info=\"");
159|        escape_xml_str(xml, node->as.code.info);
160|        cmark_strbuf_putc(xml, '"');
161|      }
162|      cmark_strbuf_puts(xml, " xml:space=\"preserve\">");
163|      escape_xml(xml, node->data, node->len);
164|      cmark_strbuf_puts(xml, "</");
165|      cmark_strbuf_puts(xml, cmark_node_get_type_string(node));
166|      literal = true;
167|      break;
168|    case CMARK_NODE_CUSTOM_BLOCK:
169|    case CMARK_NODE_CUSTOM_INLINE:
170|      cmark_strbuf_puts(xml, " on_enter=\"");
171|      escape_xml_str(xml, node->as.custom.on_enter);
172|      cmark_strbuf_putc(xml, '"');
173|      cmark_strbuf_puts(xml, " on_exit=\"");
174|      escape_xml_str(xml, node->as.custom.on_exit);
175|      cmark_strbuf_putc(xml, '"');
176|      break;
177|    case CMARK_NODE_LINK:
178|    case CMARK_NODE_IMAGE:
179|      cmark_strbuf_puts(xml, " destination=\"");
180|      escape_xml_str(xml, node->as.link.url);
181|      cmark_strbuf_putc(xml, '"');
182|      if (node->as.link.title) {
183|        cmark_strbuf_puts(xml, " title=\"");
184|        escape_xml_str(xml, node->as.link.title);
185|        cmark_strbuf_putc(xml, '"');
186|      }
187|      break;
188|    default:
189|      break;
190|    }
191|    if (node->first_child) {
192|      state->indent += 2;
193|    } else if (!literal) {
194|      cmark_strbuf_puts(xml, " /");
195|    }
196|    cmark_strbuf_puts(xml, ">\n");
197|
198|  } else if (node->first_child) {
199|    state->indent -= 2;
200|    indent(state);
201|    cmark_strbuf_puts(xml, "</");
202|    cmark_strbuf_puts(xml, cmark_node_get_type_string(node));
203|    cmark_strbuf_puts(xml, ">\n");
204|  }
205|
206|  return 1;
207|}

