182|static void add_line(cmark_chunk *ch, cmark_parser *parser) {
183|  int chars_to_tab;
184|  int i;
185|  if (parser->partially_consumed_tab) {
186|    parser->offset += 1; // skip over tab
187|    // add space characters:
188|    chars_to_tab = TAB_STOP - (parser->column % TAB_STOP);
189|    for (i = 0; i < chars_to_tab; i++) {
190|      cmark_strbuf_putc(&parser->content, ' ');
