704|// Find first nonspace character from current offset, setting
705|// parser->first_nonspace, parser->first_nonspace_column,
706|// parser->indent, and parser->blank. Does not advance parser->offset.
707|static void S_find_first_nonspace(cmark_parser *parser, cmark_chunk *input) {
708|  char c;
709|  int chars_to_tab = TAB_STOP - (parser->column % TAB_STOP);
710|
711|  if (parser->first_nonspace <= parser->offset) {
712|    parser->first_nonspace = parser->offset;
713|    parser->first_nonspace_column = parser->column;
714|    while ((c = peek_at(input, parser->first_nonspace))) {
715|      if (c == ' ') {
716|        parser->first_nonspace += 1;
717|        parser->first_nonspace_column += 1;
718|        chars_to_tab = chars_to_tab - 1;
719|        if (chars_to_tab == 0) {
720|          chars_to_tab = TAB_STOP;
721|        }
722|      } else if (c == '\t') {
723|        parser->first_nonspace += 1;
724|        parser->first_nonspace_column += chars_to_tab;
725|        chars_to_tab = TAB_STOP;
726|      } else {
727|        break;
728|      }
729|    }
730|  }
731|
732|  parser->indent = parser->first_nonspace_column - parser->column;
733|  parser->blank = S_is_line_end_char(peek_at(input, parser->first_nonspace));
734|}
735|
736|// Advance parser->offset and parser->column.  parser->offset is the
737|// byte position in input; parser->column is a virtual column number
738|// that takes into account tabs. (Multibyte characters are not taken
739|// into account, because the Markdown line prefixes we are interested in
740|// analyzing are entirely ASCII.)  The count parameter indicates
741|// how far to advance the offset.  If columns is true, then count
742|// indicates a number of columns; otherwise, a number of bytes.
743|// If advancing a certain number of columns partially consumes
744|// a tab character, parser->partially_consumed_tab is set to true.
745|static void S_advance_offset(cmark_parser *parser, cmark_chunk *input,
746|                             bufsize_t count, bool columns) {
747|  char c;
748|  int chars_to_tab;
749|  int chars_to_advance;
750|  while (count > 0 && (c = peek_at(input, parser->offset))) {
751|    if (c == '\t') {
752|      chars_to_tab = TAB_STOP - (parser->column % TAB_STOP);
753|      if (columns) {
754|        parser->partially_consumed_tab = chars_to_tab > count;
755|        chars_to_advance = MIN(count, chars_to_tab);
756|        parser->column += chars_to_advance;
757|        parser->offset += (parser->partially_consumed_tab ? 0 : 1);
758|        count -= chars_to_advance;
759|      } else {
760|        parser->partially_consumed_tab = false;
761|        parser->column += chars_to_tab;
762|        parser->offset += 1;
763|        count -= 1;
764|      }
765|    } else {
766|      parser->partially_consumed_tab = false;
767|      parser->offset += 1;
768|      parser->column += 1; // assume ascii; block starts are ascii
769|      count -= 1;
770|    }
771|  }
