862|static bool parse_html_block_prefix(cmark_parser *parser,
863|                                    cmark_node *container) {
864|  bool res = false;
865|  int html_block_type = container->as.html_block_type;
866|
867|  assert(html_block_type >= 1 && html_block_type <= 7);
868|  switch (html_block_type) {
869|  case 1:
870|  case 2:
871|  case 3:
872|  case 4:
873|  case 5:
874|    // these types of blocks can accept blanks
875|    res = true;
876|    break;
877|  case 6:
878|  case 7:
879|    res = !parser->blank;
880|    break;
881|  }
882|
883|  return res;
