1282|    cmark_strbuf_put(&parser->curline, buffer, bytes);
1283|
1284|  bytes = parser->curline.size;
1285|
1286|  // ensure line ends with a newline:
1287|  if (bytes == 0 || !S_is_line_end_char(parser->curline.ptr[bytes - 1]))
1288|    cmark_strbuf_putc(&parser->curline, '\n');
1289|
1290|  parser->offset = 0;
1291|  parser->column = 0;
1292|  parser->first_nonspace = 0;
1293|  parser->first_nonspace_column = 0;
1294|  parser->thematic_break_kill_pos = 0;
1295|  parser->indent = 0;
1296|  parser->blank = false;
1297|  parser->partially_consumed_tab = false;
