1492|      skip_spaces(&subj);
1493|      if (!skip_line_end(&subj)) {
1494|        return 0;
1495|      }
1496|    } else {
1497|      return 0;
1498|    }
1499|  }
1500|  // insert reference into refmap
1501|  cmark_reference_create(refmap, &lab, &url, &title);
